// Page Peel / Page Loop / Page Roll as VEGAS draws them with GPU acceleration on (vfxpage.h): the transitions' float OpenCL kernels, re-implemented. Standalone (the header has no
// dependencies): g++ -std=c++17 -O1 tests/engine/vfxpage_test.cpp -o vfxpage_test && ./vfxpage_test
//
// The expected pixels come from VEGAS's own kernels run on the CPU in float (the OpenCL C source decoded from the DLL, a small host shim, the CPU processors' setup in numpy) on
// two 64 x 36 test pictures; the table is the output of that run (60 pixel values and the sum of every value of the picture, per case). The same code also matches VEGAS's captured pictures
// (320 x 180, 121 cases): mean difference 0.02 level, the largest 1 level except two single pixels whose sample sits within 5e-5 of the frame's edge, where the card's asin decides.
// What is checked besides: the settings handed to the kernels (peelSetup / loopSetup / rollSetup).
#include "../../src/ofx/vfxpage.h"
#include <cmath>
#include <cstdio>
#include <vector>

using namespace reno::ofx::vfxpage;

static int gPass = 0, gFail = 0;
static void check(bool ok, const char* name, const char* detail = "")
{
    if (ok) { ++gPass; std::printf("PASS %s %s\n", name, detail); }
    else { ++gFail; std::printf("FAIL %s %s\n", name, detail); }
}

// generated by gen.py from the kernels run on the CPU (clang, float, no FMA contraction)
