static const int kPix[12][2] = {{2, 2}, {10, 5}, {20, 10}, {33, 18}, {40, 25}, {55, 30}, {61, 33}, {5, 30}, {30, 3}, {47, 12}, {15, 20}, {60, 2}};

static const int w = 64, h = 36;

// the two test pictures, rows bottom first (the formulas count rows from the top, as the generator does)
static void makePics(std::vector<float>& A, std::vector<float>& B)
{
    A.assign((size_t)w * h * 4, 0.f);
    B.assign((size_t)w * h * 4, 0.f);
    for (int yb = 0; yb < h; ++yb) {
        const int y = h - 1 - yb;
        for (int x = 0; x < w; ++x) {
            float* a = &A[((size_t)yb * w + x) * 4];
            float* b = &B[((size_t)yb * w + x) * 4];
            a[0] = (float)((double)x / (w - 1)); a[1] = (float)((double)y / (h - 1)); a[2] = (float)(((x * 7 + y * 3) % 16) / 15.0); a[3] = 1.f;
            b[0] = (float)(1 - (double)x / (w - 1)); b[1] = (float)(((x * 5 + y * 11) % 32) / 31.0); b[2] = (float)(1 - (double)y / (h - 1)); b[3] = 1.f;
        }
    }
}

int main()
{
    std::vector<float> A, B;
    makePics(A, B);
    Img ia, ib;
    ia.p = A.data(); ia.w = w; ia.h = h;
    ib.p = B.data(); ib.w = w; ib.h = h;
    const char* const names[3] = {"Page Peel", "Page Loop", "Page Roll"};
    int n = 0;
    for (const Case& cs : kCases) {
        std::vector<float> out((size_t)w * h * 4, -1.f);
        if (cs.eff == 0) {
            const PeelSetup s = peelSetup(w, h, cs.prog, cs.angle, cs.a1, cs.a2, cs.a3, cs.a4, cs.rgb);
            const Geo g = makeGeo(w, h, s.sn, s.cs, 1.0f);
            renderFrame(g, ib, out.data(), 0, h, [&](float a, float b, float* col) { peelSample(g, s, ia, a, b, col); });
        } else if (cs.eff == 1) {
            const LoopSetup s = loopSetup(w, h, cs.prog, cs.angle, cs.a1, cs.a2, cs.a3, cs.a4, cs.rgb);
            const Geo g = makeGeo(w, h, s.sn, s.cs, 1.0f);
            renderFrame(g, ia, out.data(), 0, h, [&](float a, float b, float* col) { loopSample(g, s, ib, a, b, col); });
        } else {
            const RollSetup s = rollSetup(w, h, cs.prog, cs.angle, cs.a1, cs.a2, cs.a3, cs.a4, cs.rgb);
            const Geo g = makeGeo(w, h, s.sn, s.cs, 1.0f);
            renderFrame(g, ib, out.data(), 0, h, [&](float a, float b, float* col) { rollSample(g, s, ia, a, b, col); });
        }
        double worst = 0, sum = 0;
        for (int i = 0; i < 12; ++i) {
            const float* q = &out[((size_t)kPix[i][1] * w + kPix[i][0]) * 4];
            for (int k = 0; k < 4; ++k) worst = std::max(worst, (double)std::fabs(q[k] - (float)cs.px[i][k]));
        }
        for (float v : out) sum += v;
        char name[96], detail[96];
        std::snprintf(name, sizeof name, "%s case %d: pixels match the kernel", names[cs.eff], n);
        std::snprintf(detail, sizeof detail, "(worst %.2e, sum %.4f vs %.4f)", worst, sum, cs.sum);
        check(worst < 2e-5 && std::fabs(sum - cs.sum) < 2e-3, name, detail);
        ++n;
    }
    {
        // the nearest 8-bit level of a float that is exactly half way goes to the lower level (vegasTiesDown): the kernels' pictures are stored that way
        check(std::ceil(0.5 * 255.0 - 0.5) == 127.0 && std::ceil(0.4 * 255.0 - 0.5) == 102.0, "ties go down", "");
    }
    std::printf("\n%d passed, %d failed\n", gPass, gFail);
    return gFail ? 1 : 0;
}
